class LFSR32 {
  constructor(seed) {
    // Seed cannot be 0 for a standard LFSR
    this.state = seed & 0xffffffff || 0xace1
  }

  // Generates a 32-bit unsigned integer
  nextUint32() {
    let bit =
      ((this.state >>> 0) ^
        (this.state >>> 1) ^
        (this.state >>> 2) ^
        (this.state >>> 22)) &
      1

    this.state = ((this.state >>> 1) | (bit << 31)) >>> 0
    return this.state
  }

  // Replaces rng.random() -> Returns a float between 0.0 (inclusive) and 1.0 (exclusive)
  random() {
    return this.nextUint32() / 0x100000000 // Divide by 2^32
  }
}
const rng = new LFSR32(12345)

function getManName(ee) {
  return Object.entries(manager).find((e) => e[1] == ee)?.[0]
}
oncontextmenu = (e) => {
  e.preventDefault()
  manager.x = test.get_mouseX() - 15
  manager.y = test.get_mouseY() - 30
}

function killPlayer() {
  manager.activateDeadFunc = 1
  newObserveObject.gOver = 0
  test.dead(true)
}

function startNewBattle() {
  manager.attacked.set_x(manager.char[0].get_x() - 85)
  manager.attacked.set_y(manager.char[0].get_y() + 20)
  if (manager.attacked.get_x() < 0) {
    manager.attacked.set_x(0)
  }
  manager.attacked.set_visible(true)
  if (test.fightThemePlaying == 0) {
    test.fightThemePlay()
  }
  test.removeListeners()
  test.attackedTimer.start()
}

