function pmax() {
  manager.magic[Enum.Magic.lightning] = 99
  // manager.skills[Enum.Skill.reveal] = 0.01
  manager.emeralds += 9999
  manager.gold += 99990000
  manager.keys += 99990000
  manager.medallions += 99990000
  manager.shadowCrest += 99990000
  manager.skillPoints += 999999
  manager.mp = manager.mxmp += 9999999
  manager.hp = manager.mxhp += 9999999
  manager.str += 999999
  manager.loot.fill(999)
  manager.minB = 999
  manager.speed = 20
  manager.slamstones += 99999
  manager.rubies += 9999
  manager.correct += 9999
}

window.escPressed = 0
var enterKeyPressed = false
var lastSpeedAdjuster = null
window.onkeydown = (e) => {
  log(e.key.toLowerCase())
  const { key } = e
  // TODO slow mode
  if (["shift"].includes(e.key.toLowerCase())) {
    window.useSlowSpeed = 1
  }
  if (["esc", "escape"].includes(e.key.toLowerCase())) {
    e.preventDefault()
    window.escPressed = 1
    test.stage.dispatchEvent({
      type: "mouseDown",
      isDefaultPrevented() {
        return true
      },
    })
    window.escPressed = 0
  }
  if (["enter", "\n"].includes(e.key.toLowerCase())) {
    e.preventDefault()
    enterKeyPressed = true
    managerInstance.ClickHandler()
    enterKeyPressed = false
  }
  // TODO not in combat/menu
  if (key == "f" && !test.fightMode) test.save()
  if (key == "e") {
    manager.messFin = true
  }
  if (key == "q") test.newScreen()
  // if (key == "z") manager.speed = 4000
  if (key == "a") {
    manager.realeast--
    test.newScreen()
  }
  if (key == "w") {
    manager.realnorth--
    test.newScreen()
  }
  if (key == "s") {
    manager.realnorth++
    test.newScreen()
  }
  if (key == "d") {
    manager.realeast++
    test.newScreen()
  }
  if (key == "l") {
    fetch("//fs.localhost/./pos", {
      body: `[${manager.realnorth},${manager.realeast}],`,
      method: "PUT",
    }).then((e) => e.text().then(log))
  }
  if (e.key.toLowerCase() == "p") {
    e.preventDefault()
    test.BattleSetUp()
  }
}
window.onkeyup = ({ key }) => {
  if (key == "Shift") window.useSlowSpeed = 0
}
onblur = () => {
  window.useSlowSpeed = 0
}
