      manager.AddCommas = function (loopCounter) {
        var loopCounter2 = 0
        for (; loopCounter >= 1e6; ) {
          ++loopCounter2
          loopCounter -= 1e6
        }
        var remainingOperations = 0
        for (; loopCounter >= 1e5; ) {
          ++remainingOperations
          loopCounter -= 1e5
        }
        var m = 0
        for (; loopCounter >= 1e4; ) {
          ++m
          loopCounter -= 1e4
        }
        var multiplierPerMillion = 0
        for (; loopCounter >= 1e3; ) {
          ++multiplierPerMillion
          loopCounter -= 1e3
        }
        var loopAdjustment = 0
        for (; loopCounter >= 100; ) {
          ++loopAdjustment
          loopCounter -= 100
        }
        var multiStepCalculation = 0
        for (; loopCounter >= 10; ) {
          ++multiStepCalculation
          loopCounter -= 10
        }
        var forLoopCounter = 0
        for (; loopCounter > 0; ) {
          ++forLoopCounter
          --loopCounter
        }
        if (loopCounter2 > 0) {
          return (
            (loopCounter2 | 0) +
            "," +
            (remainingOperations | 0) +
            "" +
            (m | 0) +
            "" +
            (multiplierPerMillion | 0) +
            "," +
            (loopAdjustment | 0) +
            "" +
            (multiStepCalculation | 0) +
            "" +
            (forLoopCounter | 0)
          )
        } else if (remainingOperations > 0) {
          return (
            (remainingOperations | 0) +
            "" +
            (m | 0) +
            "" +
            (multiplierPerMillion | 0) +
            "," +
            (loopAdjustment | 0) +
            "" +
            (multiStepCalculation | 0) +
            "" +
            (forLoopCounter | 0)
          )
        } else if (m > 0) {
          return (
            (m | 0) +
            "" +
            (multiplierPerMillion | 0) +
            "," +
            (loopAdjustment | 0) +
            "" +
            (multiStepCalculation | 0) +
            "" +
            (forLoopCounter | 0)
          )
        } else if (multiplierPerMillion > 0) {
          return (
            (multiplierPerMillion | 0) +
            "," +
            (loopAdjustment | 0) +
            "" +
            (multiStepCalculation | 0) +
            "" +
            (forLoopCounter | 0)
          )
        } else if (loopAdjustment > 0) {
          return F3.string(
            (loopAdjustment | 0) +
              "" +
              (multiStepCalculation | 0) +
              "" +
              (forLoopCounter | 0),
          )
        } else if (multiStepCalculation > 0) {
          return F3.string(
            (multiStepCalculation | 0) + "" + (forLoopCounter | 0),
          )
        } else if (forLoopCounter > 0) {
          return F3.string(forLoopCounter | 0)
        } else {
          return "0"
        }
      }
