          AttackBonusFunc: function () {
            manager.attBonTitle.set_visible(false)
            manager.attBonDisplay.set_visible(false)
            manager.attBonAni = 0
            manager.attBonGauge.set_x(181)
            manager.attBonFirstTime = false
            var randomRange = Math.ceil(rng.random() * 1e6)
            var randomValue = 0
            if (manager.boostHits > 0) {
              randomValue = (manager.str + manager.dmg) | 0
            }
            var totalDamage = manager.str + manager.dmg + randomValue
            if (manager.weapon[Enum.Weapon.riskTaker] == 2) {
              totalDamage =
                manager.str +
                ((100 - (manager.hp / manager.mxhp) * 100) | 0) * 2 +
                randomValue
            }
            if (
              manager.weapon[Enum.Weapon.rageBlade] == 2 &&
              manager.rageStones > 0
            ) {
              totalDamage += 100
              manager.rageStones--
            }
            if (
              (manager.mobVar == ObjectCreator.onyxEater ||
                manager.mobVar == ObjectCreator.jurgulTusk ||
                manager.mobVar == ObjectCreator.stalwarg) &&
              manager.weaknessTriggered == 0
            ) {
              totalDamage = 0
            }
            if (
              (objectFactory2.equals(
                manager.mobName.get_text(),
                "WIGHT",
              ) ||
                objectFactory2.equals(
                  manager.mobName.get_text(),
                  "CHORTHIS",
                )) &&
              manager.weapon[Enum.Weapon.flameStaff] != 2 &&
              manager.weapon[Enum.Weapon.manaBow] != 2
            ) {
              totalDamage = 0
            }
            if (
              manager.weapon[Enum.Weapon.katsuNi] == 2 ||
              manager.weapon[Enum.Weapon.katsuShi] == 2
            ) {
              randomRange = 0
            }
            if (
              manager.ninTics > 0 &&
              (manager.weapon[Enum.Weapon.katsuNi] == 2 ||
                manager.weapon[Enum.Weapon.katsuShi] == 2) &&
              manager.NM <= 0
            ) {
              manager.BatMesEdit("Instant victory!!!", 16776960)
              this.MHPEdit(-manager.mHP)
            } else if (randomRange <= manager.cor) {
              manager.BatMesEdit(
                "You score a QUADRUPLE HIT, inflicting " +
                  F3.string(totalDamage * 4) +
                  " damage!!!",
                16776960,
              )
              this.MHPEdit(-totalDamage * 4)
            } else if (
              randomRange / 100 <= manager.cor ||
              manager.weapon[Enum.Weapon.rongmarsClub] == 2 ||
              manager.ninTics > 0
            ) {
              manager.BatMesEdit(
                "You score a TRIPLE HIT, inflicting " +
                  F3.string(totalDamage * 3) +
                  " damage!!!",
                16776960,
              )
              this.MHPEdit(-totalDamage * 3)
            } else {
              manager.BatMesEdit(
                "You strike with a furious blow, inflicting " +
                  F3.string(totalDamage * 2) +
                  " damage!",
                16776960,
              )
              this.MHPEdit(-totalDamage * 2)
            }
            manager.attBonSound.play()
          },
