          BombSmokeStarter: function (c) {
            if (manager.quest[Enum.Quest.ransom] < 11) {
              manager.smokeYellow[0].set_x(c.get_x())
              manager.smokeYellow[0].set_y(c.get_y())
              manager.smokeYellow[0].set_alpha(1)
              manager.smokeYellow[0].set_visible(true)
              manager.colSmoke.set_width(100)
              manager.colSmoke.set_height(100)
              manager.colSmoke.set_x(manager.smokeYellow[0].get_x())
              manager.colSmoke.set_y(manager.smokeYellow[0].get_y())
            } else if (
              manager.quest[Enum.Quest.ransom] >= 11 &&
              manager.quest[Enum.Quest.ransom] < 20
            ) {
              manager.smokeRed[0].set_x(c.get_x() - 50)
              manager.smokeRed[0].set_y(c.get_y() - 50)
              manager.smokeRed[0].set_alpha(1)
              manager.smokeRed[0].set_visible(true)
              manager.colSmoke.set_width(200)
              manager.colSmoke.set_height(200)
              manager.colSmoke.set_x(manager.smokeRed[0].get_x())
              manager.colSmoke.set_y(manager.smokeRed[0].get_y())
            } else if (manager.quest[Enum.Quest.ransom] >= 20) {
              manager.smokeRed[0].set_x(0)
              manager.smokeRed[0].set_y(0)
              manager.smokeRed[0].set_alpha(1)
              manager.smokeRed[0].set_visible(true)
              c = 0
              for (
                var bombSmokeStarterHandler = manager.smokeRed.length;
                c < bombSmokeStarterHandler;
              ) {
                var cSmokePos = c++
                manager.smokeRed[cSmokePos].set_scaleX(4)
                manager.smokeRed[cSmokePos].set_scaleY(3.5)
              }
              manager.colSmoke.set_width(900)
              manager.colSmoke.set_height(650)
              manager.colSmoke.set_x(manager.smokeRed[0].get_x())
              manager.colSmoke.set_y(manager.smokeRed[0].get_y())
            }
          },
          BattleMagicChecker: function () {
            for (
              var currentIndex = 0, allMagicValid = false;
              currentIndex < manager.magic.length;
            ) {
              if (
                manager.magic[currentIndex] > 0 &&
                (currentIndex == 1 ||
                  currentIndex == 2 ||
                  currentIndex == 3 ||
                  currentIndex == 4 ||
                  currentIndex == 5 ||
                  currentIndex == 6 ||
                  currentIndex == 7 ||
                  currentIndex == 8 ||
                  currentIndex == 9 ||
                  currentIndex == 10 ||
                  currentIndex == 11 ||
                  currentIndex == 12 ||
                  currentIndex == 13 ||
                  currentIndex == 16 ||
                  currentIndex == 17 ||
                  currentIndex == 19 ||
                  currentIndex == 21 ||
                  currentIndex == Enum.Magic.zeal ||
                  currentIndex == Enum.Magic.energize)
              ) {
                allMagicValid = true
              }
              ++currentIndex
            }
            return allMagicValid
          },
