          BackToBattle: function () {
            manager.prob.set_visible(true)
            manager.cursor.set_visible(true)
            this.showSkills =
              this.showItems =
              this.showQuests =
              this.showFood =
              this.showMagic =
              this.showArmor =
              this.showWeapons =
              this.showWindow =
                false
            manager.shopMess.set_alpha(0)
            this.equippedSlot.set_alpha(0)
            if (manager.mSpecAttBar.get_scaleX() > 0) {
              manager.mSpecAttBar.set_visible(true)
              manager.mSpecAttGauge.set_visible(true)
            }
            if (manager.ninTics > 0) {
              manager.titles[manager.ninjaMode].set_visible(true)
            }
            if (manager.shieldBlocks > 0) {
              manager.icon[Enum.Icon.shield].set_visible(true)
            }
            if (manager.fireTics <= 0) {
              manager.icon[Enum.Icon.fireIcon].set_visible(false)
            }
            if (manager.toxinPow > 0) {
              manager.icon[Enum.Icon.toxinIcon].set_visible(true)
            }
            if (manager.chillTics <= 0) {
              manager.icon[Enum.Icon.chillIcon].set_visible(false)
              manager.chillPow = 0
            }
            if (
              objectFactory2.equals(
                manager.mobName.get_text(),
                "SIR STALWARG",
              ) &&
              manager.weaknessTriggered == 0 &&
              manager.icon[Enum.Icon.stalShieldIcon].get_visible() ==
                0
            ) {
              manager.icon[Enum.Icon.stalShieldIcon].set_visible(true)
            }
            for (
              var minimizedFunction = 0,
                showUIElements = this.slot.length;
              minimizedFunction < showUIElements;
            ) {
              var a = minimizedFunction++
              this.slot[a].set_alpha(0)
              this.slotDisplay[a].set_alpha(0)
            }
            minimizedFunction = 0
            for (
              showUIElements = manager.weaponGraphic.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              manager.weaponGraphic[a].set_alpha(0)
            }
            minimizedFunction = 0
            for (
              showUIElements = manager.armorGraphic.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              manager.armorGraphic[a].set_alpha(0)
            }
            minimizedFunction = 0
            for (
              showUIElements = manager.magicGraphic.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              manager.magicGraphic[a].set_alpha(0)
              this.magicDisplay[a].set_alpha(0)
            }
            minimizedFunction = 0
            for (
              showUIElements = this.slotItem.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              this.slotItem[a] = -1
            }
            minimizedFunction = 0
            for (
              showUIElements = manager.questDisplay.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              manager.questDisplay[a].set_alpha(0)
            }
            minimizedFunction = 0
            for (
              showUIElements = manager.itemDisplay.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              manager.itemDisplay[a].set_visible(false)
            }
            minimizedFunction = 0
            for (
              showUIElements = manager.food.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              manager.foodGraphic[a].set_alpha(0)
              this.foodDisplay[a].set_alpha(0)
              this.foodEffect[a].set_alpha(0)
              this.slotFood[a].set_alpha(0)
            }
            minimizedFunction = 0
            for (
              showUIElements = manager.skill.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              manager.skillGraphic[a].set_alpha(0)
            }
            minimizedFunction = 0
            for (
              showUIElements = this.colMagic.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              this.colMagic[a].set_visible(false)
            }
            minimizedFunction = 0
            for (
              showUIElements = manager.batMes.length;
              minimizedFunction < showUIElements;
            ) {
              a = minimizedFunction++
              manager.batMes[a].set_visible(true)
            }
            this.showBattle = true
            manager.ClearButtons(-1)
            manager.butCancel.set_alpha(0)
            manager.butPrev.set_alpha(0)
            manager.butNext.set_alpha(0)
            manager.shopMess.set_alpha(0)
            if (manager.fightMode == 1 && manager.mobile == 0) {
              manager.butMagicKeyGuide.set_visible(true)
            }
            this.getProb()
          },
