          getProb: function () {
            console.log("getting new problem")
            manager.placeInNumber = 0
            manager.anDisplay.set_text("")
            manager.anDisplay.set_x(manager.pBox.get_x() + 180)
            manager.icon[Enum.Icon.check].set_visible(false)
            manager.icon[Enum.Icon.ex].set_visible(false)
            manager.probDelay = 0
            var cLevel = 1
            if (manager.level > 9) {
              cLevel = Math.ceil(rng.random() * 2)
            }
            if (manager.level > 19) {
              cLevel = Math.ceil(rng.random() * 3)
            }
            if (manager.level > 29) {
              cLevel = Math.ceil(rng.random() * 4)
            }
            if (cLevel == 1) {
              cLevel = Math.ceil(rng.random() * 9)
              var a_level_delay =
                manager.level < 9 ?
                  Math.ceil(rng.random() * manager.level)
                : Math.ceil(rng.random() * 9)
              manager.an = cLevel + a_level_delay
              manager.prob.set_text(
                cLevel + " + " + a_level_delay + " =",
              )
            } else if (cLevel == 2) {
              cLevel = Math.ceil(rng.random() * 9)
              a_level_delay =
                manager.level < 19 ?
                  Math.ceil(rng.random() * (manager.level - 9))
                : Math.ceil(rng.random() * 9)
              manager.an = cLevel
              manager.prob.set_text(
                cLevel + a_level_delay + " - " + a_level_delay + " =",
              )
            } else if (cLevel == 3) {
              cLevel = Math.ceil(rng.random() * 9)
              a_level_delay =
                manager.level < 29 ?
                  Math.ceil(rng.random() * (manager.level - 19))
                : Math.ceil(rng.random() * 9)
              manager.an = cLevel * a_level_delay
              manager.prob.set_text(
                cLevel + " x " + a_level_delay + " =",
              )
            } else if (cLevel == 4) {
              cLevel = Math.ceil(rng.random() * 9)
              a_level_delay =
                manager.level < 39 ?
                  Math.ceil(rng.random() * (manager.level - 29))
                : Math.ceil(rng.random() * 9)
              manager.an = cLevel
              manager.prob.set_text(
                cLevel * a_level_delay + " ÷ " + a_level_delay + " =",
              )
            }
            manager.prob.setTextFormat(manager.probFormat)
            manager.prob.set_visible(true)
            manager.cursor.set_visible(true)
            manager.digits =
              manager.an < 10 ? 1
              : manager.an > 9 && manager.an < 100 ? 2
              : 3
            manager.cursor.set_x(manager.pBox.get_x() + 174)
            if (manager.mobile == 0 && manager.mHP > 0) {
              this.stage.addEventListener(
                "keyDown",
                extendPrototype(this, this.anInputHandler),
              )
              console.log("input handler added")
            }
            if (manager.mobile == 1 && manager.mHP > 0) {
              this.stage.addEventListener(
                "mouseDown",
                extendPrototype(this, this.mobileAnInputHandler),
              )
              this.ShowNumButs()
              console.log("mobile input handler added")
            }
          },
