          TextFieldSetup: function (
            textElement,
            embedFontsValue,
            _textFieldSetupPosition,
            textAreaPosition,
            textFieldX,
            textFieldContent,
            visible,
            mouseEnabled,
            textFieldFormat,
          ) {
            textElement.set_embedFonts(true)
            textElement.set_selectable(false)
            textElement.mouseEnabled = false
            textElement.set_x(textAreaPosition)
            textElement.set_y(textFieldX + manager.mOffset)
            textElement.set_width(embedFontsValue)
            textElement.set_height(_textFieldSetupPosition)
            textElement.set_visible(visible)
            textElement.set_alpha(mouseEnabled)
            textElement.set_wordWrap(true)
            textElement.set_multiline(true)
            textElement.set_text(textFieldContent)
            textElement.setTextFormat(textFieldFormat)
            this.addChild(textElement)
          },
          TextFieldEdit: function (
            TextFieldEditor,
            textB,
            fieldFormat,
          ) {
            manager.gaugeFormat.color = 16777215
            TextFieldEditor.set_text(textB)
            TextFieldEditor.setTextFormat(fieldFormat)
            TextFieldEditor.set_visible(true)
            TextFieldEditor.set_alpha(1)
          },
          MHPEdit: function (damageAmount) {
            if (manager.weaknessTriggered == 0) {
              damageAmount = 0
            }
            manager.mHP += damageAmount
            if (
              objectFactory2.equals(
                manager.mobName.get_text(),
                "DOOMED KNIGHT",
              ) &&
              manager.deathByFire == 0 &&
              manager.mHP <= 0
            ) {
              manager.mHP = 1
            }
            if (manager.mHP < 0) {
              manager.mHP = 0
              this.stage.removeEventListener(
                "keyDown",
                extendPrototype(this, this.anInputHandler),
              )
              this.stage.removeEventListener(
                "mouseDown",
                extendPrototype(this, this.mobileAnInputHandler),
              )
              this.RemoveNumButs()
              this.mobSmoke[0].set_x(0)
              this.mobSmoke[0].set_y(-10)
              this.mobSmoke[0].set_visible(true)
              manager.setBombSound.play()
              if (
                manager.icon[
                  Enum.Icon.stalShieldIcon
                ].get_visible() == 1
              ) {
                manager.icon[Enum.Icon.stalShieldIcon].set_visible(
                  false,
                )
              }
            }
            manager.ShowMobStats()
          },
