          PlaceSlots: function () {
            for (
              var itemIndex = 0, slotLength = this.slot.length;
              itemIndex < slotLength;
            ) {
              var slotIndex = itemIndex++
              this.slot[slotIndex].set_x(manager.window.get_x() + 40)
              this.slot[slotIndex].set_y(
                manager.window.get_y() + 70 + slotIndex * 145,
              )
              if (slotIndex >= 3) {
                this.slot[slotIndex].set_x(
                  manager.window.get_x() + 330,
                )
                this.slot[slotIndex].set_y(
                  manager.window.get_y() + 70 + (slotIndex - 3) * 145,
                )
              }
            }
          },
          PlaceGraphic: function (graphicSetter, slotIndex) {
            graphicSetter.set_x(this.slot[slotIndex].get_x())
            graphicSetter.set_y(this.slot[slotIndex].get_y())
            graphicSetter.set_alpha(0.01)
          },
          PlaceMagicGraphic: function (
            placeholder,
            bX,
            graphicPositionY,
          ) {
            manager.magicGraphic[placeholder].set_x(bX)
            manager.magicGraphic[placeholder].set_y(graphicPositionY)
            manager.magicGraphic[placeholder].set_alpha(0.01)
            this.colMagic[placeholder].set_x(
              manager.magicGraphic[placeholder].get_x(),
            )
            this.colMagic[placeholder].set_y(
              manager.magicGraphic[placeholder].get_y(),
            )
            this.colMagic[placeholder].set_visible(true)
            this.magicDisplay[placeholder].set_x(
              manager.magicGraphic[placeholder].get_x() + 105,
            )
            this.magicDisplay[placeholder].set_y(
              manager.magicGraphic[placeholder].get_y(),
            )
            this.magicDisplay[placeholder].set_alpha(0.01)
          },
