          ShowButtons: function () {
            for (
              var currentColumnIndex = 0,
                sideButtonCount = manager.sideButton.length;
              currentColumnIndex < sideButtonCount;
            ) {
              var currentIndex = currentColumnIndex++
              manager.sideButton[currentIndex].set_visible(true)
              manager.sideDisplay[currentIndex].set_visible(true)
              if (manager.fightMode == 1 && currentIndex == 8) {
                manager.sideButton[8].set_visible(false)
                manager.sideDisplay[8].set_visible(false)
              }
            }
            if (manager.confuseTics > 0) {
              manager.confuseIcon.set_visible(true)
            }
            if (
              manager.quest[Enum.Quest.bombQuest] >= 4 &&
              manager.fightMode == 0
            ) {
              manager.BombEdit(0)
              manager.bombButton.set_visible(true)
              manager.bombDisplay.set_visible(true)
            }
          },
          NewSkillShow: function (skillIndex) {
            console.log("new skill")
            manager.mess.set_alpha(1)
            manager.skillGraphic[skillIndex].set_x(350)
            manager.skillGraphic[skillIndex].set_y(440)
            manager.skillGraphic[skillIndex].set_alpha(1)
            manager.skill[skillIndex] = 1
            manager.butYes.set_alpha(1)
          },
