          GetWizWrongs: function () {
            for (
              var randomNumber, cRandomNumber, currentGuessDifference;
              (randomNumber = Math.ceil(rng.random() * 89) + 10),
                (currentGuessDifference = Math.abs(
                  randomNumber - manager.wwAnswer,
                )),
                (randomNumber % 2 == 0 &&
                  manager.wwAnswer % 2 == 0) ||
                  (randomNumber % 2 == 1 &&
                    manager.wwAnswer % 2 == 1) ||
                  currentGuessDifference > 10;
            );
            while (
              ((cRandomNumber = Math.ceil(rng.random() * 89) + 10),
              (currentGuessDifference = Math.abs(
                cRandomNumber - manager.wwAnswer,
              )),
              currentGuessDifference < 10 ||
                currentGuessDifference > 20)
            );
            if (manager.corWiz == 0) {
              manager.wizNumber[1] = randomNumber
              manager.wizNumber[2] = cRandomNumber
            } else if (manager.corWiz == 1) {
              manager.wizNumber[0] = randomNumber
              manager.wizNumber[2] = cRandomNumber
            } else if (manager.corWiz == 2) {
              manager.wizNumber[0] = randomNumber
              manager.wizNumber[1] = cRandomNumber
            }
          },
          BattleSetUp: function () {
            this.showWindow = false
            this.RemoveInputListeners()
            manager.ClearButtons(-1)
            var trackedMobIndex = 0
            if (manager.trackedMob == 0) {
              manager.titles[0].set_x(manager.char[0].get_x() - 50)
              manager.titles[0].set_y(manager.char[0].get_y() + 50)
            } else {
              manager.titles[19].set_x(manager.char[0].get_x() - 100)
              manager.titles[19].set_y(manager.char[0].get_y() + 50)
              trackedMobIndex = 19
            }
            if (manager.char[0].get_x() < 0) {
              manager.titles[trackedMobIndex].set_x(0)
            } else if (manager.char[0].get_x() > 600) {
              manager.titles[trackedMobIndex].set_x(500)
            }
            if (manager.char[0].get_y() < 0) {
              manager.titles[trackedMobIndex].set_y(50)
            } else if (manager.char[0].get_y() > 500) {
              manager.titles[trackedMobIndex].set_y(570)
            }
            manager.titles[trackedMobIndex].set_alpha(1)
            manager.attDelay = 0
            if (
              manager.icon[Enum.Icon.pointerIcon].get_visible() == 1
            ) {
              manager.icon[Enum.Icon.pointerIcon].set_visible(false)
              manager.firstQuest = false
            }
            if (manager.ring[Enum.Ring.zealRing] >= 2) {
              manager.zealTics += 100
            }
            this.stage.addEventListener(
              "mouseUp",
              extendPrototype(this, this.backToBattleFunc),
            )
            this.BattleThemeFunc()
          },
