      F2.BookMess = function () {
        for (
          var currentCodeValue = manager.cataCode,
            currentValue = 0,
            southDirection = 0;
          currentCodeValue >= 100;
        ) {
          ++currentValue
          currentCodeValue -= 100
        }
        while (currentCodeValue >= 10) {
          ++southDirection
          currentCodeValue -= 10
        }
        currentCodeValue =
          currentCodeValue + southDirection + currentValue
        if (manager.north == 850 && manager.east == 850) {
          manager.mess.set_text(
            "Scribe the cipher to reveal the guardian.",
          )
        }
        if (manager.north == 849 && manager.east == 850) {
          if (manager.cataCode % 2 == 0) {
            manager.mess.set_text(
              "Only an even cipher shall call forth the magic within.",
            )
          } else {
            manager.mess.set_text(
              "Only an odd cipher shall call forth the magic within.",
            )
          }
        }
        if (manager.north == 850 && manager.east == 849) {
          manager.mess.set_text(
            "The sum of the three digits in the cipher is " +
              currentCodeValue +
              ".",
          )
        }
        if (manager.north == 850 && manager.east == 851) {
          currentCodeValue = Math.floor(rng.random() * 2)
          if (currentCodeValue == 0 && currentValue > 1) {
            manager.mess.set_text(
              "The cipher contains " + currentValue + " hundreds.",
            )
          }
          if (currentCodeValue == 1 && southDirection > 1) {
            manager.mess.set_text(
              "The cipher contains " + southDirection + " tens.",
            )
          }
          if (currentCodeValue == 0 && currentValue == 1) {
            manager.mess.set_text(
              "The cipher contains " + currentValue + " hundred.",
            )
          }
          if (currentCodeValue == 1 && southDirection == 1) {
            manager.mess.set_text(
              "The cipher contains " + southDirection + " ten.",
            )
          }
        }
      }
